/**
 * Trusted, human-authored GOLD REFERENCE fixtures for the cross_version12 suite.
 * They verify executable test specifications against real npm releases locally.
 * These are NOT generated by an LLM; NEVER include them in model Pass@1 results.
 * The runner will execute candidate code ONLY in Docker, not on the host.
 */
'use strict';
const fs = require('node:fs');
const path = require('node:path');

const ROOT = path.resolve(__dirname,'..');
const TASKS = JSON.parse(fs.readFileSync(path.join(ROOT,'milestone3','tasks.json'),'utf8'));
const SPECS = JSON.parse(fs.readFileSync(path.join(ROOT,'milestone3','execution_specs.json'),'utf8'));
const target = path.join(ROOT,'milestone3','npm_workspaces','reference12','golden.jsonl');
const byId = new Map(TASKS.map(t => [t.id,t]));

function expressApp(method,route,body) {
  return 'module.exports = function setup(express) { const app = express(); app.' +
    method + '(' + JSON.stringify(route) + ', (req,res) => {' + body +
    '}); return app; };';
}
function mongooseApp(operation) {
  return 'module.exports = function setup(mongoose) { const Model = mongoose.model(' +
    '"ExampleRecord", new mongoose.Schema({ name: String })); return ' + operation + '; };';
}
const answers = new Map([
  ['express-wildcard-task-new', expressApp('get','/{*splat}','res.sendStatus(200);')],
  ['express-del-task-new', expressApp('delete','/item','res.sendStatus(200);')],
  ['mongoose-remove-task-new', mongooseApp('filter => Model.deleteMany(filter)')],
  ['mongoose-update-task-new', mongooseApp('(filter,change) => Model.updateOne(filter, {$set: change})')],
  ['express-wildcard-task-old', expressApp('get','/*','res.sendStatus(200);')],
  ['express-del-task-old', expressApp('del','/item','res.sendStatus(200);')],
  ['express-basic-route-task-old', expressApp('get','/health',"res.send('ok');")],
  ['express-basic-route-task-new', expressApp('get','/health',"res.send('ok');")],
  ['mongoose-remove-task-old', mongooseApp('filter => Model.remove(filter)')],
  ['mongoose-update-task-old', mongooseApp('(filter,change) => Model.update(filter, {$set: change})')],
  ['mongoose-findbyid-task-old', mongooseApp('id => Model.findById(id)')],
  ['mongoose-findbyid-task-new', mongooseApp('id => Model.findById(id)')]
]);

if (answers.size !== 12 || Object.keys(SPECS).length !== 12) throw Error('Expected exactly 12 current executable specifications');
const rows = [];
for (const [id,code] of answers) {
  const task = byId.get(id), spec = SPECS[id];
  if (!task || !spec || task.package !== spec.package || task.target_version !== spec.version) {
    throw Error('Unverified task metadata / installed version: ' + id);
  }
  rows.push({task_id:id,package:spec.package,target_version:spec.version,
    method:'reference_gold_not_llm',model:'human_authored_fixture',
    code, source:'manually authored trusted preflight; exclude from model comparisons'});
}
fs.mkdirSync(path.dirname(target),{recursive:true});
fs.writeFileSync(target,rows.map(r=>JSON.stringify(r)).join('\n')+'\n');
console.log('Wrote '+rows.length+' HUMAN-AUTHORED reference fixtures to '+target);
console.log('Run with Docker for BENCHMARK VALIDATION only; never report as LLM results.');
